trigger_evidence:
Alert.alert(
      "Saved Offline",
      message ||
        "No network. Lifecycle instruction saved to offline forms queue.",
      [
        {
          text: "OK",
          onPress: () => router.back(),
        },
      ],
    )

Alert.alert(
        "TRN Created",
        result?.message || "Lifecycle instruction created successfully.",
        [
          {
            text: "OK",
            onPress: () => router.back(),
          },
        ],
      )

buildFailureResult(
          "UNAUTHORIZED_LCT_ORIGINATOR",
          "Only MNG can create lifecycle instructions",
          {
            actorRole: authority.role,
            actorRelationshipType: authority.relationshipType,
            actorClientType: authority.clientType,
          },
        )

buildFailureResult(
          assignmentCheck.code,
          assignmentCheck.message,
          {
            trnId,
            trnType,
            astId,
          },
        )

buildFailureResult(
          "INSTRUCTION_MEDIA_REQUIRED",
          "Instruction media is required when assignment.instruction.mediaRequired is true",
          {
            trnId,
            trnType,
            astId,
          },
        )

buildFailureResult(
            "TRN_ALREADY_EXISTS",
            "A TRN with this id already exists",
            {
              trnId,
              trnType,
              astId,
            },
          )

buildFailureResult(
            "AST_NOT_FOUND",
            "The referenced AST does not exist",
            {
              trnId,
              trnType,
              astId,
            },
          )

buildFailureResult(
            "PREMISE_NOT_FOUND",
            "The referenced premise does not exist",
            {
              trnId,
              trnType,
              astId,
              premiseId,
            },
          )

buildFailureResult(
            eligibilityCheck.code,
            eligibilityCheck.message,
            {
              trnId,
              trnType,
              astId,
            },
          )

{
      ok: false,
      code: "INVALID_TRN_ID",
      message: "TRN id is required",
    }

{
      ok: false,
      code: "INVALID_OFFICE_LCT_TYPE",
      message:
        "Only INSPECTION, DISCONNECTION, RECONNECTION, REMOVAL and METER READING instructions can be created from Operations.",
    }

{
      ok: false,
      code: "INVALID_AST_ID",
      message: "astId is required",
    }

{
      ok: false,
      code: "INVALID_PREMISE_ID",
      message: "premiseId is required",
    }

{
        ok: false,
        code: "INVALID_AST_STATE",
        message: "DECOMMISSIONED meters cannot be issued for inspection",
      }

{
        ok: false,
        code: "INVALID_AST_STATE",
        message: "Only CONNECTED meters can be issued for disconnection",
      }

{
        ok: false,
        code: "INVALID_AST_STATE",
        message: "Only DISCONNECTED meters can be issued for reconnection",
      }

{
        ok: false,
        code: "INVALID_AST_STATE",
        message: "This meter has already been removed",
      }

{
        ok: false,
        code: "INVALID_AST_STATE",
        message: "DECOMMISSIONED meters cannot be issued for meter reading",
      }

{
        ok: false,
        code: "PREPAID_MREAD_NOT_SUPPORTED",
        message: "MREAD Sprint 1 supports conventional meters only",
      }

{
    ok: false,
    code: "INVALID_OFFICE_LCT_TYPE",
    message: "Unsupported lifecycle instruction type",
  }
